const { name, slug, isoDate, order, website } = $items(0).json;
const body = $json.choices?.[0]?.message?.content || '';
const social = { android:"", apple:"", facebook:"", twitter:"", instagram:"", youtube:"", linkedin:"", reddit:"", whatsapp:"", tiktok:"", telegram:"", website, wikipedia:"" };
const description = `An in-depth review of ${name}: features, security, fees, and regulations.`;
const frontmatterLines = [ '---', `title: "${name}"`, `image: "/images/exchanges/${slug}.png"`, `description: "${description}"`, `date: ${isoDate}`, `order: ${order}`, `authors: ["Crypto Wiki Team"]`, 'social:', ...Object.entries(social).map(([k,v])=>`  ${k}: ${v}`), 'draft: true', '---',''];
const mdx = frontmatterLines.join('\n') + body.trim() + '\n';
return [{ json: { mdx, slug } }];

const { db, slug, name, order } = $items(0).json;
db.exchanges = db.exchanges || {};
db.exchanges[slug] = { slug: `/exchanges/${slug}`, title: name, order };
db.next_orders = db.next_orders || {};
db.next_orders.exchanges = order + 1;
const newDbText = JSON.stringify(db, null, 2)+"\n";
return [{ json: { newDbText, slug } }];
